{
  "intent": "aggregate",
  "target": "tracks",
  "filters": {
    "classes": ["person"],
    "time_range": {
      "kind": "named",
      "name": "today"
    }
  },
  "group_by": ["camera"],
  "order": {
    "by": "value",
    "direction": "desc"
  },
  "limit": 1000,
  "visual_query": "average dwell time of people per camera today"
}

